def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]

    # Locate the full-length divider.
    horizontal = next((r for r in range(h) if all(g[r][c] == 2 for c in range(w))), None)
    vertical = next((c for c in range(w) if all(g[r][c] == 2 for r in range(h))), None)

    if horizontal is None and vertical is None:
        return g

    # The background is the most common color other than the divider color.
    counts = {}
    for row in g:
        for value in row:
            if value != 2:
                counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    points = [(r, c) for r in range(h) for c in range(w)
              if g[r][c] != bg and g[r][c] != 2]
    if not points:
        return g

    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)

    if horizontal is not None:
        s = horizontal
        shift = (s + 1 - r0) if r0 > s else (s - 1 - r1)
        patch = [row[c0:c1 + 1] for row in g[r0:r1 + 1]]

        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                g[r][c] = bg
        nr0 = r0 + shift
        for i, row in enumerate(patch):
            g[nr0 + i][c0:c1 + 1] = row

        marker_row = nr0 + len(patch) if nr0 > s else nr0 - 1
        if 0 <= marker_row < h:
            g[marker_row] = [8] * w
    else:
        s = vertical
        shift = (s + 1 - c0) if c0 > s else (s - 1 - c1)
        patch = [g[r][c0:c1 + 1] for r in range(r0, r1 + 1)]

        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                g[r][c] = bg
        nc0 = c0 + shift
        for i, row in enumerate(patch):
            g[r0 + i][nc0:nc0 + len(row)] = row

        marker_col = nc0 + (c1 - c0 + 1) if nc0 > s else nc0 - 1
        if 0 <= marker_col < w:
            for r in range(h):
                g[r][marker_col] = 8

    return g
